                thread_by_id[tid] = t
        else:
            # keep existing (no clear preference)
            pass
    else:
        thread_by_id[tid] = t

# Candidate delete lists derived earlier: inbox_delete and outbox_delete
candidate_ids = [t['email_thread_id'] for t in inbox_delete] + [t['email_thread_id'] for t in outbox_delete]
unique_delete_ids = sorted(set(candidate_ids))

# Verification table for unique deletes
print('Unique delete count:', len(unique_delete_ids))
print('Unique delete ids:', unique_delete_ids)

print('VERIFICATION TABLE (unique to be deleted):')
for tid in unique_delete_ids:
    t = thread_by_id.get(tid)
    if t is None:
        print('MISSING THREAD RECORD FOR id', tid)
        continue
